import React, { useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function SignupPage() {
  const { userType } = useParams();
  const { signup } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "", email: "", password: "",
    specialization: "", isAvailable: false, availableFrom: "", availableTo: "",
  });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm({ ...form, [name]: type === "checkbox" ? checked : value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      await signup({ ...form, userType });
      navigate(userType === "doctor" ? "/doctor/dashboard" : "/patient/dashboard");
    } catch (err) {
      setError(err.response?.data?.message || "Signup failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-wrapper">
      <div className="card auth-card" style={{ maxWidth: 520 }}>
        <div style={{ textAlign: "center", marginBottom: "1.5rem" }}>
          <div style={{ fontSize: "2.5rem" }}>{userType === "doctor" ? "👨‍⚕️" : "🏥"}</div>
          <h2 className="card-title" style={{ marginTop: ".5rem" }}>
            Create {userType === "doctor" ? "Doctor" : "Patient"} Account
          </h2>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Full Name</label>
            <input className="form-control" name="name" required value={form.name} onChange={handleChange} placeholder="John Doe" />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input className="form-control" type="email" name="email" required value={form.email} onChange={handleChange} placeholder="you@email.com" />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input className="form-control" type="password" name="password" required value={form.password} onChange={handleChange} placeholder="Min 8 characters" minLength={8} />
          </div>

          {userType === "doctor" && (
            <>
              <div className="form-group">
                <label>Specialization</label>
                <input className="form-control" name="specialization" value={form.specialization} onChange={handleChange} placeholder="e.g. Neurologist" />
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Available From</label>
                  <input className="form-control" type="time" name="availableFrom" value={form.availableFrom} onChange={handleChange} />
                </div>
                <div className="form-group">
                  <label>Available To</label>
                  <input className="form-control" type="time" name="availableTo" value={form.availableTo} onChange={handleChange} />
                </div>
              </div>
              <div className="form-group" style={{ display: "flex", alignItems: "center", gap: ".6rem" }}>
                <input type="checkbox" name="isAvailable" id="isAvailable" checked={form.isAvailable} onChange={handleChange} />
                <label htmlFor="isAvailable" style={{ marginBottom: 0 }}>Mark as available now</label>
              </div>
            </>
          )}

          <button className="btn btn-primary btn-block" type="submit" disabled={loading}>
            {loading ? <><span className="spinner"></span> Creating account…</> : "Create Account"}
          </button>
        </form>

        <div className="auth-footer">
          Already have an account? <Link to={`/login/${userType}`}>Sign in</Link>
          {" | "}
          <Link to="/">← Back</Link>
        </div>
      </div>
    </div>
  );
}
